 assert tokens(x['source_xml'],r'\\b(?:deux|trois|six) (?:mois|ans)|cinquante communes|un an')==tokens(y['proposed_xml'],r'\\b(?:deux|trois|six) (?:mois|ans)|cinquante communes|un an')
